#!/bin/zsh
# 分步上手引导：欢迎、连接设备、模型、权限一览、可选功能。
cd "$(dirname "$0")"
gen() {
  local name=$1; local prompt=$2
  [ -f "$name.png" ] && return
  local t0=$(date +%s)
  codex exec --skip-git-repo-check --ephemeral -c 'model_reasoning_effort="low"' -C "$PWD" -s workspace-write \
    "请使用内置的 image_gen 工具生成一张高保真 UI 设计稿（像设计师在 Figma 里做的最终稿截图，正视图、不要透视、纯浅灰背景上只放这一个窗口）：$prompt 生成后把最终图片复制到当前目录，命名为 $name.png，然后只回复文件名。" < /dev/null > "$name.log" 2>&1
  echo "$name $(( $(date +%s) - t0 ))s $([ -f $name.png ] && echo ok || echo FAIL)"
}
S="这是 macOS 桌面应用「豆仓」（把录音转成文字、整理成纪要）。浅色模式。设计语言：苹果 macOS 最新系统的风格加乔纳森·艾维式的克制——圆角卡片、细分隔线、说明是小号灰字、对齐严谨、留白舒服。配色严格限定：暖灰纸色背景（#FAF9F7）、卡片纯白、深暖灰文字（#1C1917）、唯一强调色玫瑰红（#F43F5E，用在主按钮、选中状态）；绝对不要蓝色、紫色、青色、彩虹色。界面文字全部是简体中文，字体像苹方，清晰可读、没有乱码。"
gen ui_onboarding "【上手引导·权限这一步】一个 macOS 弹出窗口（sheet），宽约 860、高约 600，白色圆角。左边一条窄的步骤栏（暖灰底 #F5F5F4），顶部是一个小仓鼠头像戴耳机（奶白色、萌、软绒质感）和「豆仓」两个字，下面竖排 6 个步骤，每个步骤是圆形序号+名字：「1 欢迎」（已完成：玫瑰红实心圆+白色对勾）、「2 连接录音豆」（已完成）、「3 转写模型」（已完成）、「4 整理纪要的模型」（灰色空心序号，旁边小灰字「跳过了」）、「5 权限」（当前步：浅玫瑰红底高亮整行）、「6 更多功能」（灰色）。右边主区域：大标题「豆仓需要的权限」，副标题灰字「每一项都写了用来做什么。没开的点「去打开」，会直接跳到系统设置里对应的地方；开好回来这里会自动变成已开。」下面是一张白色列表卡片，5 行，每行：左边圆角方块里的单色图标（暖灰），中间粗体名字+一行灰色小字说明，右边状态：已开的写绿色小圆点+「已开」，没开的是次要按钮「去打开」。5 行分别是：「蓝牙」——连接录音豆和录音卡（已开）；「麦克风」——用 Mac 自己录音（已开）；「屏幕与系统录音」——录会议软件、视频里的电脑声音（按钮「去打开」）；「辅助功能」——语音输入时把文字打进别的软件（按钮「去打开」）；「通知」——录音整理好了、录音豆连上了告诉你（已开）。卡片下面一行灰字「不开也能用：没开的那项功能用不了，其它照常。」右下角两个按钮：次要「上一步」，主按钮玫瑰红「下一步」；左下角一个灰色文字按钮「跳过引导」。整体克制、留白舒服。$S"
